5	 * You may obtain a copy of Mulan PSL v2 at:
6	 *          http://license.coscl.org.cn/MulanPSL2
7	 * THIS SOFTWARE IS PROVIDED ON AN "AS IS" BASIS, WITHOUT WARRANTIES OF ANY KIND,
8	 * EITHER EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT,
9	 * MERCHANTABILITY OR FIT FOR A PARTICULAR PURPOSE.
10	 * See the Mulan PSL v2 for more details. */
11	// Author: Chen, Qixiang
12	// Description:
13	`include "define.v"
14	//`include "IDecode_define.v"
15	
16	`timescale 1ns/1ps
17	
18	// Arbitrating which reading (TO DO: writing) request should be send to register files
19	module operand_arbiter(
20	  input                                                 clk                       ,
21	  input                                                 rst_n                     ,
22	
23	  // input interface
24	  input  [4*`NUM_COLLECTORUNIT-1:0]                     arbiter_valid_i           ,
25	  input  [`DEPTH_BANK*4*`NUM_COLLECTORUNIT-1:0]         arbiter_bankID_i          , // arbiter_bankID_i[ID(7)(3),ID(7)(2),ID(7)(1),ID(7)(0),ID(6)(3)...ID(0)(1),ID(0)(0)]
26	  input  [2*4*`NUM_COLLECTORUNIT-1:0]                   arbiter_rsType_i          , // rsType(num_collector)(num_operand)
27	  input  [`DEPTH_REGBANK*4*`NUM_COLLECTORUNIT-1:0]      arbiter_rsAddr_i          ,
28	  
29	  // output interface
30	  output  [`NUM_BANK-1:0]                               scalar_valid_o            ,
31	  //input   [`NUM_BANK-1:0]                               scalar_ready_i            ,
32	  //output  [`DEPTH_BANK*`NUM_BANK-1:0]                   scalar_bankID_o           , // scalar_bankID_o[ID(3),ID(2),ID(1),ID(0)]
33	  //output  [2*`NUM_BANK-1:0]                             scalar_rsType_o           , // ID(num_bank)
34	  output  [`DEPTH_REGBANK*`NUM_BANK-1:0]                scalar_rsAddr_o           ,
35	
36	  output  [`NUM_BANK-1:0]                               vector_valid_o            ,
37	  //input   [`NUM_BANK-1:0]                               vector_ready_i            ,
38	  //output  [`DEPTH_BANK*`NUM_BANK-1:0]                   vector_bankID_o           ,
39	  //output  [2*`NUM_BANK-1:0]                             vector_rsType_o           ,
40	  output  [`DEPTH_REGBANK*`NUM_BANK-1:0]                vector_rsAddr_o           ,
41	  
42	  output  [$clog2(4*`NUM_COLLECTORUNIT)*`NUM_BANK-1:0]  chosen_scalar_o           , // chosen_scalar_o[chosen(3),chosen(2),chosen(1),chosen(0)]
43	  output  [$clog2(4*`NUM_COLLECTORUNIT)*`NUM_BANK-1:0]  chosen_vector_o             // chosen(num_bank)
44	);
45	
46	  parameter DEPTH_4_COLLECTORUNIT = $clog2(4*`NUM_COLLECTORUNIT);
47	
48	  //wire [`DEPTH_BANK*4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]         arbiter_scalar_bankID_in          ; // arbiter_scalar_bankID_in[bank(3),bank(2),bank(1),bank(0)],bank(i) have 4*`NUM_COLLECTORUNIT bankID
49	  //wire [2*4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]                   arbiter_scalar_rsType_in          ;
50	  wire [`DEPTH_REGBANK*4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]      arbiter_scalar_rsAddr_in          ;  
51	  wire [4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]                     arbiter_scalar_valid_in           ;  
52	  //wire [4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]                     arbiter_scalar_ready_in           ;
53	  //wire [`DEPTH_BANK*`NUM_BANK-1:0]                              arbiter_scalar_bankID_out         ; // arbiter_scalar_bankID_out[bank(3),bank(2),bank(1),bank(0)],bank(i) have one bankID
54	  //wire [2*`NUM_BANK-1:0]                                        arbiter_scalar_rsType_out         ;
55	  wire [`DEPTH_REGBANK*`NUM_BANK-1:0]                           arbiter_scalar_rsAddr_out         ;
56	  wire [`NUM_BANK-1:0]                                          arbiter_scalar_valid_out          ;
57	  //wire [`NUM_BANK-1:0]                                          arbiter_scalar_ready_out          ;
58	  wire [DEPTH_4_COLLECTORUNIT*`NUM_BANK-1:0]                    arbiter_scalar_chosen             ;
59	
60	  //wire [`DEPTH_BANK*4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]         arbiter_vector_bankID_in          ;
61	  //wire [2*4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]                   arbiter_vector_rsType_in          ;
62	  wire [`DEPTH_REGBANK*4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]      arbiter_vector_rsAddr_in          ;
63	  wire [4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]                     arbiter_vector_valid_in           ;
64	  //wire [4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]                     arbiter_vector_ready_in           ;
65	  //wire [`DEPTH_BANK*`NUM_BANK-1:0]                              arbiter_vector_bankID_out         ;
66	  //wire [2*`NUM_BANK-1:0]                                        arbiter_vector_rsType_out         ;
67	  wire [`DEPTH_REGBANK*`NUM_BANK-1:0]                           arbiter_vector_rsAddr_out         ;
68	  wire [`NUM_BANK-1:0]                                          arbiter_vector_valid_out          ;
69	  //wire [`NUM_BANK-1:0]                                          arbiter_vector_ready_out          ;
70	  wire [DEPTH_4_COLLECTORUNIT*`NUM_BANK-1:0]                    arbiter_vector_chosen             ;
71	
72	  wire [4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]                     arbiter_scalar_valid_oh           ;
73	  wire [4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]                     arbiter_vector_valid_oh           ;
74	
75	  //wire [`DEPTH_BANK*4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]         arbiter_scalar_bankID_out_oh      ; 
76	  //wire [2*4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]                   arbiter_scalar_rsType_out_oh      ;
77	  wire [`DEPTH_REGBANK*4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]      arbiter_scalar_rsAddr_out_oh      ;
78	  //wire [`DEPTH_BANK*4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]         arbiter_vector_bankID_out_oh      ; 
79	  //wire [2*4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]                   arbiter_vector_rsType_out_oh      ;
80	  wire [`DEPTH_REGBANK*4*`NUM_COLLECTORUNIT*`NUM_BANK-1:0]      arbiter_vector_rsAddr_out_oh      ;
81	  
82	  // arbiter input_num:4*`NUM_COLLECTORUNIT, ouput_num:one
83	  // mapping input signals from collector units to inputs of Arbiters
84	  genvar n;
85	  generate
86	    for (n=0; n<`NUM_BANK; n=n+1) begin:bank_loop_1
87	      //assign arbiter_scalar_bankID_in[`DEPTH_BANK*4*`NUM_COLLECTORUNIT*(n+1)-1-:`DEPTH_BANK*4*`NUM_COLLECTORUNIT]               = arbiter_bankID_i;
88	      //assign arbiter_scalar_rsType_in[2*4*`NUM_COLLECTORUNIT*(n+1)-1-:2*4*`NUM_COLLECTORUNIT]                                   = arbiter_rsType_i;
89	      assign arbiter_scalar_rsAddr_in[`DEPTH_REGBANK*4*`NUM_COLLECTORUNIT*(n+1)-1-:`DEPTH_REGBANK*4*`NUM_COLLECTORUNIT]         = arbiter_rsAddr_i;
90	      //assign arbiter_vector_bankID_in[`DEPTH_BANK*4*`NUM_COLLECTORUNIT*(n+1)-1-:`DEPTH_BANK*4*`NUM_COLLECTORUNIT]               = arbiter_bankID_i;
91	      //assign arbiter_vector_rsType_in[2*4*`NUM_COLLECTORUNIT*(n+1)-1-:2*4*`NUM_COLLECTORUNIT]                                   = arbiter_rsType_i;
92	      assign arbiter_vector_rsAddr_in[`DEPTH_REGBANK*4*`NUM_COLLECTORUNIT*(n+1)-1-:`DEPTH_REGBANK*4*`NUM_COLLECTORUNIT]         = arbiter_rsAddr_i;
93	
94	      assign arbiter_scalar_valid_out[n] = |arbiter_scalar_valid_in[4*`NUM_COLLECTORUNIT*(n+1)-1-:4*`NUM_COLLECTORUNIT]; 
95	      assign arbiter_vector_valid_out[n] = |arbiter_vector_valid_in[4*`NUM_COLLECTORUNIT*(n+1)-1-:4*`NUM_COLLECTORUNIT]; 
96	
97	      //assign  arbiter_scalar_bankID_out[`DEPTH_BANK*(n+1)-1-:`DEPTH_BANK] = 
98	      //        arbiter_scalar_bankID_out_oh[`DEPTH_BANK*4*`NUM_COLLECTORUNIT*n+(arbiter_scalar_chosen[DEPTH_4_COLLECTORUNIT*(n+1)-1-:DEPTH_4_COLLECTORUNIT]+1)*`DEPTH_BANK-1-:`DEPTH_BANK];
99	      
100	      //assign  arbiter_scalar_rsType_out[2*(n+1)-1-:2] = 
101	      //        arbiter_scalar_rsType_out_oh[2*4*`NUM_COLLECTORUNIT*n+(arbiter_scalar_chosen[DEPTH_4_COLLECTORUNIT*(n+1)-1-:DEPTH_4_COLLECTORUNIT]+1)*2-1-:2];
102	      
103	      assign  arbiter_scalar_rsAddr_out[`DEPTH_REGBANK*(n+1)-1-:`DEPTH_REGBANK] = 
104	              arbiter_scalar_rsAddr_out_oh[`DEPTH_REGBANK*4*`NUM_COLLECTORUNIT*n+(arbiter_scalar_chosen[DEPTH_4_COLLECTORUNIT*(n+1)-1-:DEPTH_4_COLLECTORUNIT]+1)*`DEPTH_REGBANK-1-:`DEPTH_REGBANK];
105	      
106	      //assign  arbiter_vector_bankID_out[`DEPTH_BANK*(n+1)-1-:`DEPTH_BANK] = 
107	      //        arbiter_vector_bankID_out_oh[`DEPTH_BANK*4*`NUM_COLLECTORUNIT*n+(arbiter_vector_chosen[DEPTH_4_COLLECTORUNIT*(n+1)-1-:DEPTH_4_COLLECTORUNIT]+1)*`DEPTH_BANK-1-:`DEPTH_BANK];
108	      
109	      //assign  arbiter_vector_rsType_out[2*(n+1)-1-:2] = 
110	      //        arbiter_vector_rsType_out_oh[2*4*`NUM_COLLECTORUNIT*n+(arbiter_vector_chosen[DEPTH_4_COLLECTORUNIT*(n+1)-1-:DEPTH_4_COLLECTORUNIT]+1)*2-1-:2];
111	      
112	      assign  arbiter_vector_rsAddr_out[`DEPTH_REGBANK*(n+1)-1-:`DEPTH_REGBANK] = 
113	              arbiter_vector_rsAddr_out_oh[`DEPTH_REGBANK*4*`NUM_COLLECTORUNIT*n+(arbiter_vector_chosen[DEPTH_4_COLLECTORUNIT*(n+1)-1-:DEPTH_4_COLLECTORUNIT]+1)*`DEPTH_REGBANK-1-:`DEPTH_REGBANK];
114	    end
115	  endgenerate
116	  
117	  // elaborate valid port of readArbiters  
118	  genvar i,j,k;
119	  generate
120	    for (i=0; i<`NUM_BANK; i=i+1) begin:bank_loop_2
121	      for (j=0; j<`NUM_COLLECTORUNIT; j=j+1) begin:collector_unit_loop_2
122	        for (k=0; k<4; k=k+1) begin:operand_loop_2
123	          assign arbiter_scalar_valid_in[4*`NUM_COLLECTORUNIT*i+j*4+k] = arbiter_valid_i[j*4+k] && (arbiter_bankID_i[(j*4+k+1)*`DEPTH_BANK-1-:`DEPTH_BANK]==i)
124	                                                                          && (arbiter_rsType_i[(j*4+k+1)*2-1-:2]==2'b01);
125	          assign arbiter_vector_valid_in[4*`NUM_COLLECTORUNIT*i+j*4+k] = arbiter_valid_i[j*4+k] && (arbiter_bankID_i[(j*4+k+1)*`DEPTH_BANK-1-:`DEPTH_BANK]==i)
126	                                                                          && (arbiter_rsType_i[(j*4+k+1)*2-1-:2]==2'b10 || arbiter_rsType_i[(j*4+k+1)*2-1-:2]==2'b00);
127	
128	          //assign arbiter_vector_valid_in[4*`NUM_COLLECTORUNIT*i+j*4+k] = arbiter_valid_i[j*4+k] && (arbiter_bankID_i[(j*4+k+1)*`DEPTH_BANK-1-:`DEPTH_BANK]==i)
129	          //                                                                && (arbiter_rsType_i[(j*4+k+1)*2-1-:2]==2'b00);
130	          //assign arbiter_scalar_bankID_out_oh[`DEPTH_BANK*4*`NUM_COLLECTORUNIT*i+(j*4+k+1)*`DEPTH_BANK-1-:`DEPTH_BANK] = 
131	          //       arbiter_scalar_valid_in[4*`NUM_COLLECTORUNIT*i+j*4+k] ? arbiter_scalar_bankID_in[`DEPTH_BANK*4*`NUM_COLLECTORUNIT*i+(j*4+k+1)*`DEPTH_BANK-1-:`DEPTH_BANK] : 'b0;
132	          
133	          //assign arbiter_scalar_rsType_out_oh[2*4*`NUM_COLLECTORUNIT*i+(j*4+k+1)*2-1-:2] = 
134	          //       arbiter_scalar_valid_in[4*`NUM_COLLECTORUNIT*i+j*4+k] ? arbiter_scalar_rsType_in[2*4*`NUM_COLLECTORUNIT*i+(j*4+k+1)*2-1-:2] : 'b0;
135	          
136	          assign arbiter_scalar_rsAddr_out_oh[`DEPTH_REGBANK*4*`NUM_COLLECTORUNIT*i+(j*4+k+1)*`DEPTH_REGBANK-1-:`DEPTH_REGBANK] = 
137	                 arbiter_scalar_valid_in[4*`NUM_COLLECTORUNIT*i+j*4+k] ? arbiter_scalar_rsAddr_in[`DEPTH_REGBANK*4*`NUM_COLLECTORUNIT*i+(j*4+k+1)*`DEPTH_REGBANK-1-:`DEPTH_REGBANK] : 'b0;
138	          
139	          //assign arbiter_vector_bankID_out_oh[`DEPTH_BANK*4*`NUM_COLLECTORUNIT*i+(j*4+k+1)*`DEPTH_BANK-1-:`DEPTH_BANK] = 
140	          //       arbiter_vector_valid_in[4*`NUM_COLLECTORUNIT*i+j*4+k] ? arbiter_vector_bankID_in[`DEPTH_BANK*4*`NUM_COLLECTORUNIT*i+(j*4+k+1)*`DEPTH_BANK-1-:`DEPTH_BANK] : 'b0;
141	          
142	          //assign arbiter_vector_rsType_out_oh[2*4*`NUM_COLLECTORUNIT*i+(j*4+k+1)*2-1-:2] = 
143	          //       arbiter_vector_valid_in[4*`NUM_COLLECTORUNIT*i+j*4+k] ? arbiter_vector_rsType_in[2*4*`NUM_COLLECTORUNIT*i+(j*4+k+1)*2-1-:2] : 'b0;
144	          
145	          assign arbiter_vector_rsAddr_out_oh[`DEPTH_REGBANK*4*`NUM_COLLECTORUNIT*i+(j*4+k+1)*`DEPTH_REGBANK-1-:`DEPTH_REGBANK] = 
146	                 arbiter_vector_valid_in[4*`NUM_COLLECTORUNIT*i+j*4+k] ? arbiter_vector_rsAddr_in[`DEPTH_REGBANK*4*`NUM_COLLECTORUNIT*i+(j*4+k+1)*`DEPTH_REGBANK-1-:`DEPTH_REGBANK] : 'b0;
147	
148	        end
149	      end
150	    end
151	  endgenerate
152	
153	
154	  //assign arbiter_scalar_ready_in  = {4*`NUM_COLLECTORUNIT*`NUM_BANK{1'b1}}     ; // TODO generatefor
155	  //assign arbiter_vector_ready_in  = {4*`NUM_COLLECTORUNIT*`NUM_BANK{1'b1}}     ;
156	  /*genvar jj,kk;
157	  generate
158	    for (jj=0; jj<`NUM_COLLECTORUNIT; jj=jj+1) begin:collector_unit_loop_3
159	      for (kk=0; kk<4; kk=kk+1) begin:operand_loop_3
160	        assign arbiter_ready_o[jj*4+kk]   = 1'b1;
161	      end
162	    end
163	  endgenerate
164	  */
165	
166	
167	
168	  assign scalar_valid_o            = arbiter_scalar_valid_out   ;
169	  //assign arbiter_scalar_ready_out  = scalar_ready_i             ;
170	  //assign scalar_bankID_o           = arbiter_scalar_bankID_out  ;
171	  //assign scalar_rsType_o           = arbiter_scalar_rsType_out  ;
172	  assign scalar_rsAddr_o           = arbiter_scalar_rsAddr_out  ;
173	
174	  assign vector_valid_o            = arbiter_vector_valid_out   ;  
175	  //assign arbiter_vector_ready_out  = vector_ready_i             ;
176	  //assign vector_bankID_o           = arbiter_vector_bankID_out  ;
177	  //assign vector_rsType_o           = arbiter_vector_rsType_out  ;
178	  assign vector_rsAddr_o           = arbiter_vector_rsAddr_out  ;
179	  
180	  assign chosen_scalar_o           = arbiter_scalar_chosen      ;
181	  assign chosen_vector_o           = arbiter_vector_chosen      ;
182	        
183	  genvar m;
184	  generate
185	    for (m=0; m<`NUM_BANK; m=m+1) begin:RRArbiter
186	      // bankArbiterScalar
187	      round_robin_arb #(
188	        .ARB_WIDTH(4*`NUM_COLLECTORUNIT)
189	      )
190	      U_round_robin_arb_scalar
191	      (
192	        .clk(clk),
193	        .rst_n(rst_n),
194	        .req(arbiter_scalar_valid_in[4*`NUM_COLLECTORUNIT*(m+1)-1-:4*`NUM_COLLECTORUNIT]),
195	        .grant(arbiter_scalar_valid_oh[4*`NUM_COLLECTORUNIT*(m+1)-1-:4*`NUM_COLLECTORUNIT])
196	      );
197	
198	      one2bin #(
199	        .ONE_WIDTH(4*`NUM_COLLECTORUNIT),
200	        .BIN_WIDTH(DEPTH_4_COLLECTORUNIT)
201	      )
202	      U_one2bin_scalar
203	      (
204	        .oh(arbiter_scalar_valid_oh[4*`NUM_COLLECTORUNIT*(m+1)-1-:4*`NUM_COLLECTORUNIT]),
205	        .bin(arbiter_scalar_chosen[DEPTH_4_COLLECTORUNIT*(m+1)-1-:DEPTH_4_COLLECTORUNIT])    
206	      );
207	      
208	      // bankArbiterVector
209	      round_robin_arb #(
210	        .ARB_WIDTH(4*`NUM_COLLECTORUNIT)
211	      )
212	      U_round_robin_arb_vector
213	      (
214	        .clk(clk),
215	        .rst_n(rst_n),
216	        .req(arbiter_vector_valid_in[4*`NUM_COLLECTORUNIT*(m+1)-1-:4*`NUM_COLLECTORUNIT]),
217	        .grant(arbiter_vector_valid_oh[4*`NUM_COLLECTORUNIT*(m+1)-1-:4*`NUM_COLLECTORUNIT])
218	      );
219	
220	      one2bin #(
221	        .ONE_WIDTH(4*`NUM_COLLECTORUNIT),
222	        .BIN_WIDTH(DEPTH_4_COLLECTORUNIT)
223	      )
224	      U_one2bin_vector
225	      (
226	        .oh(arbiter_vector_valid_oh[4*`NUM_COLLECTORUNIT*(m+1)-1-:4*`NUM_COLLECTORUNIT]),
227	        .bin(arbiter_vector_chosen[DEPTH_4_COLLECTORUNIT*(m+1)-1-:DEPTH_4_COLLECTORUNIT])    
228	      );  
229	    end
230	  endgenerate
231	
232	
233	endmodule
234

