759	        // rsAddr =  [gpr_base(i) + regIdx] / num_bank
760	        if(outArbiter_rsType_o[2*(i+1)-1-:2]==2'b01) begin
761	          if(control_fire & current_state==S_IDLE) begin
762	            outArbiter_rsAddr_o[`DEPTH_REGBANK*(i+1)-1-:`DEPTH_REGBANK] =  (sgpr_base_i[(`SGPR_ID_WIDTH+1)*(control_wid_i+1)-1-:(`SGPR_ID_WIDTH+1)] >> `DEPTH_BANK) + 
763	                                                                            (regIdx_wire[(`REGIDX_WIDTH+`REGEXT_WIDTH)*(i+1)-1:(`REGIDX_WIDTH+`REGEXT_WIDTH)*i]   >> `DEPTH_BANK);
764	          end else begin
765	            outArbiter_rsAddr_o[`DEPTH_REGBANK*(i+1)-1-:`DEPTH_REGBANK] =  (sgpr_base_i[(`SGPR_ID_WIDTH+1)*(controlReg_wid+1)-1-:(`SGPR_ID_WIDTH+1)] >> `DEPTH_BANK) + 
766	                                                                            (regIdx_reg[(`REGIDX_WIDTH+`REGEXT_WIDTH)*(i+1)-1:(`REGIDX_WIDTH+`REGEXT_WIDTH)*i]      >> `DEPTH_BANK);        
767	          end
768	        end else if(outArbiter_rsType_o[2*(i+1)-1-:2]==2'b10) begin
769	          if(control_fire & current_state==S_IDLE) begin
770	            outArbiter_rsAddr_o[`DEPTH_REGBANK*(i+1)-1-:`DEPTH_REGBANK] =  (vgpr_base_i[(`VGPR_ID_WIDTH+1)*(control_wid_i+1)-1-:(`VGPR_ID_WIDTH+1)] >> `DEPTH_BANK) + 
771	                                                                            (regIdx_wire[(`REGIDX_WIDTH+`REGEXT_WIDTH)*(i+1)-1:(`REGIDX_WIDTH+`REGEXT_WIDTH)*i]   >> `DEPTH_BANK);
772	          end else begin
773	            outArbiter_rsAddr_o[`DEPTH_REGBANK*(i+1)-1-:`DEPTH_REGBANK] =  (vgpr_base_i[(`VGPR_ID_WIDTH+1)*(controlReg_wid+1)-1-:(`VGPR_ID_WIDTH+1)] >> `DEPTH_BANK) + 
774	                                                                            (regIdx_reg[(`REGIDX_WIDTH+`REGEXT_WIDTH)*(i+1)-1:(`REGIDX_WIDTH+`REGEXT_WIDTH)*i]      >> `DEPTH_BANK);        
775	          end
776	        end else begin
777	          if(control_fire & current_state==S_IDLE) begin
778	            outArbiter_rsAddr_o[`DEPTH_REGBANK*(i+1)-1-:`DEPTH_REGBANK] =  (sgpr_base_i[(`SGPR_ID_WIDTH+1)*(control_wid_i+1)-1-:(`SGPR_ID_WIDTH+1)] >> `DEPTH_BANK) + 
779	                                                                            (regIdx_wire[(`REGIDX_WIDTH+`REGEXT_WIDTH)*(i+1)-1:(`REGIDX_WIDTH+`REGEXT_WIDTH)*i]   >> `DEPTH_BANK);
780	          end else begin
781	            outArbiter_rsAddr_o[`DEPTH_REGBANK*(i+1)-1-:`DEPTH_REGBANK] =  (sgpr_base_i[(`SGPR_ID_WIDTH+1)*(controlReg_wid+1)-1-:(`SGPR_ID_WIDTH+1)] >> `DEPTH_BANK) + 
782	                                                                            (regIdx_reg[(`REGIDX_WIDTH+`REGEXT_WIDTH)*(i+1)-1:(`REGIDX_WIDTH+`REGEXT_WIDTH)*i]      >> `DEPTH_BANK);
783	          end
784	        end
785	
786	        // outArbiter_valid
787	        case(current_state)
788	          S_IDLE: outArbiter_valid_o[i] = control_fire && ready_wire[i]==1'b0;
789	          S_ADD:  outArbiter_valid_o[i] = valid_reg[i]==1'b1 && ready_reg[i]==1'b0;
790	          default:outArbiter_valid_o[i] = 1'b0;
791	        endcase
792	      end
793	    end
794	  endgenerate
795	      
796	  always@(*) begin
797	    // operand_wire
798	    if(bankIn_fire[0] && bankIn_regOrder_i[2*(0+1)-1-:2]==2'b00) begin
799	        case(control_fire ? rsType_wire[1:0] : rsType_reg[1:0])
800	          `A1_RS1:   rsRead_wire = {`NUM_THREAD{bankIn_data_i[`XLEN*`NUM_THREAD*0+`XLEN-1-:`XLEN]}};
801	          `A1_VRS1:  rsRead_wire = {bankIn_data_i[`XLEN*`NUM_THREAD*(0+1)-1-:`XLEN*`NUM_THREAD]};
802	          default:   rsRead_wire = {`XLEN*`NUM_THREAD{1'b0}};
803	        endcase
804	    end else if(bankIn_fire[1] && bankIn_regOrder_i[2*(1+1)-1-:2]==2'b00) begin
805	        case(control_fire ? rsType_wire[1:0] : rsType_reg[1:0])
806	          `A1_RS1:   rsRead_wire = {`NUM_THREAD{bankIn_data_i[`XLEN*`NUM_THREAD*1+`XLEN-1-:`XLEN]}};
807	          `A1_VRS1:  rsRead_wire = {bankIn_data_i[`XLEN*`NUM_THREAD*(1+1)-1-:`XLEN*`NUM_THREAD]};
808	          default:   rsRead_wire = {`XLEN*`NUM_THREAD{1'b0}};
809	        endcase
810	    end else if(bankIn_fire[2] && bankIn_regOrder_i[2*(2+1)-1-:2]==2'b00) begin
811	        case(control_fire ? rsType_wire[1:0] : rsType_reg[1:0])
812	          `A1_RS1:   rsRead_wire = {`NUM_THREAD{bankIn_data_i[`XLEN*`NUM_THREAD*2+`XLEN-1-:`XLEN]}};
813	          `A1_VRS1:  rsRead_wire = {bankIn_data_i[`XLEN*`NUM_THREAD*(2+1)-1-:`XLEN*`NUM_THREAD]};
814	          default:   rsRead_wire = {`XLEN*`NUM_THREAD{1'b0}};
815	        endcase
816	    end else if(bankIn_fire[3] && bankIn_regOrder_i[2*(3+1)-1-:2]==2'b00) begin
817	        case(control_fire ? rsType_wire[1:0] : rsType_reg[1:0])
818	          `A1_RS1:   rsRead_wire = {`NUM_THREAD{bankIn_data_i[`XLEN*`NUM_THREAD*3+`XLEN-1-:`XLEN]}};
819	          `A1_VRS1:  rsRead_wire = {bankIn_data_i[`XLEN*`NUM_THREAD*(3+1)-1-:`XLEN*`NUM_THREAD]};
820	          default:   rsRead_wire = {`XLEN*`NUM_THREAD{1'b0}};
821	        endcase
822	    end else begin
823	      rsRead_wire = 'b0;
824	    end
825	  end
826	
827	  assign issue_alu_src1_o     = rs_reg[`XLEN*`NUM_THREAD-1:0];
828	  assign issue_alu_src2_o     = rs_reg[`XLEN*`NUM_THREAD*2-1:`XLEN*`NUM_THREAD*1];
829	  assign issue_alu_src3_o     = rs_reg[`XLEN*`NUM_THREAD*3-1:`XLEN*`NUM_THREAD*2];
830	  assign issue_active_mask_o  = mask_reg;
831	  
832	  assign issue_valid_o   = current_state==S_OUT;
833	  assign control_ready_o = current_state==S_IDLE && !(|valid_reg);
834	
835	
836	gen_imm U_gen_imm(
837	  .inst_i     (imm_inst)    ,
838	  .sel_i      (imm_sel)     ,
839	  .imm_ext_i  (imm_ext) , 
840	  .out_o      (imm_out)  
841	);
842	
843	endmodule
844	
845

