  input											                    in_rm_is_static_i							              ,

  input [(`SGPR_ID_WIDTH+1)*`NUM_WARP-1:0]      sgpr_base_i                                 ,
  input [(`VGPR_ID_WIDTH+1)*`NUM_WARP-1:0]      vgpr_base_i                                 ,

  input [`NUM_COLLECTORUNIT-1:0]                widCmp_i                                    ,

  // output interface
  output  [`NUM_COLLECTORUNIT-1:0]                               out_valid_o                ,
