  output  [2*`NUM_COLLECTORUNIT-1:0]                             out_mop_o                  ,
  output  [(`REGIDX_WIDTH+`REGEXT_WIDTH)*`NUM_COLLECTORUNIT-1:0] out_reg_idxw_o             ,
  output  [`NUM_COLLECTORUNIT-1:0]                               out_wvd_o                  ,
  output  [`NUM_COLLECTORUNIT-1:0]                               out_fence_o                ,
